WITH filtered AS (SELECT id, product_id, last_restock, CEIL(quantity) AS quantity_whole, ROUND(quantity, 2) AS quantity_rounded FROM inventory WHERE store_id IN (1, 2, 3, 4)), metrics AS (SELECT id, last_restock, quantity_whole, quantity_rounded, LAG(quantity_rounded) OVER w_recent AS prev_quantity_rounded, LAG(quantity_whole) OVER w_recent AS prev_quantity_whole, LEAD(quantity_whole) OVER w_recent AS next_quantity_whole, ROW_NUMBER() OVER w_recent AS event_seq FROM filtered WINDOW w_recent AS (PARTITION BY product_id ORDER BY quantity_whole, id)), with_windows AS (SELECT id, quantity_whole, prev_quantity_rounded, prev_quantity_whole, event_seq, LAG(prev_quantity_whole) OVER (ORDER BY quantity_whole, id) AS prev_prev_quantity_whole, LEAD(prev_quantity_whole) OVER (ORDER BY quantity_whole, id) AS next_prev_quantity_whole, LEAD(next_quantity_whole) OVER (ORDER BY quantity_whole, id) AS next_next_quantity_whole, ROW_NUMBER() OVER (ORDER BY quantity_whole, id) AS seq_no, PERCENT_RANK() OVER (PARTITION BY YEAR(last_restock) ORDER BY prev_quantity_whole DESC NULLS LAST) AS prev_quantity_whole_percent_rank FROM metrics), scored AS (SELECT *, LAG(prev_quantity_whole_percent_rank, 1) OVER w_ordered AS prev_prev_quantity_whole_percent_rank, ROW_NUMBER() OVER (ORDER BY prev_quantity_whole DESC, id) AS seq_no_2, DENSE_RANK() OVER (ORDER BY quantity_whole DESC) AS quantity_whole_dense_rank FROM with_windows WINDOW w_ordered AS (ORDER BY quantity_whole, id)), filtered_inventory AS (SELECT id, quantity_whole, prev_quantity_rounded, prev_quantity_whole, prev_prev_quantity_whole, next_prev_quantity_whole, next_next_quantity_whole, seq_no, prev_quantity_whole_percent_rank, seq_no_2, quantity_whole_dense_rank, ROUND(event_seq, 2) AS event_seq_rounded, ROUND(prev_quantity_whole_percent_rank, 1) AS prev_quantity_whole_percent_rank_rounded FROM scored WHERE seq_no_2 BETWEEN 5 AND 8), enriched AS (SELECT *, AVG(prev_quantity_whole_percent_rank) OVER (ORDER BY event_seq_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_prev_quantity_whole_percent_rank, SUM(prev_quantity_whole_percent_rank) OVER (ORDER BY event_seq_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_prev_quantity_whole_percent_rank, MAX(prev_quantity_whole_percent_rank) OVER (ORDER BY event_seq_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_prev_quantity_whole_percent_rank, MIN(prev_quantity_whole_percent_rank) OVER (ORDER BY event_seq_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_prev_quantity_whole_percent_rank FROM filtered_inventory), cleaned AS (SELECT *, next_next_quantity_whole * prev_prev_quantity_whole AS next_next_quantity_whole_times_prev_prev_quantity_whole FROM enriched WHERE prev_quantity_whole_percent_rank_rounded BETWEEN 40 AND 51), grouped AS (SELECT seq_no, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, MAX(quantity_whole) AS max_quantity_whole, AVG(quantity_whole) AS avg_quantity_whole, PERCENTILE_APPROX(next_prev_quantity_whole, ARRAY(0.25, 0.5, 0.75)) AS next_prev_quantity_whole_quartiles FROM cleaned GROUP BY 1 HAVING COUNT(*) > 1) SELECT seq_no, distinct_ids, max_quantity_whole, avg_quantity_whole, next_prev_quantity_whole_quartiles FROM grouped
